import {assetTypes,validAsset} from './asset-documents.js';
import {icon,assetIcon} from './icons.js';
export const escapeText=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeText,options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
export function renderDataEditor(element,doc,files,hooks){
  const d=doc.data,kind=doc.kind;
  element.innerHTML=`<header class="asset-editor-heading"><span class="asset-symbol ${kind}">${icon(assetIcon(kind))}</span><div><small>${assetTypes[kind].label}</small><h2>${esc(d.name)}</h2></div></header><div class="asset-form"></div>`;
  const form=element.querySelector('.asset-form');
  if(kind==='inputaction')form.innerHTML=`<section><h3>값</h3><label>자료형<select data-field="valueType">${options([['bool','Digital · Boolean'],['float','Axis 1D · Float'],['vec2','Axis 2D · Vector2'],['vec3','Axis 3D · Vector3']],d.valueType)}</select></label><label>데드존<input data-field="deadZone" type="number" value="${d.deadZone}" min="0" max="1" step=".05"></label></section><section><h3>트리거</h3><label>이벤트<select data-field="trigger">${options([['pressed','Started · 누를 때'],['held','Triggered · 누르는 동안'],['released','Completed · 놓을 때']],d.trigger)}</select></label><label>입력 소비<input type="checkbox" data-field="consumeInput" ${d.consumeInput?'checked':''}></label></section>`;
  if(kind==='inputmapping')form.innerHTML=`<section><h3>컨텍스트</h3><label>우선순위<input type="number" data-field="priority" min="-10000" max="10000" value="${d.priority}"></label></section><section><div class="form-section-heading"><h3>키 매핑</h3><button data-add>${icon('plus')} 매핑 추가</button></div><div class="mapping-columns"><span>Input Action</span><span>키</span><span>축</span><span>배율</span><span></span></div>${d.mappings.map((m,i)=>`<div class="mapping-row" data-index="${i}"><select data-map="action" aria-label="${i+1} 입력 액션">${options([['','선택'],...files.filter(f=>f.kind==='inputaction').map(f=>[f.path,f.name.replace('.hbinputaction.json','')])],m.action)}</select><input data-map="key" value="${esc(m.key)}" aria-label="${i+1} 키" maxlength="40"><select data-map="axis" aria-label="${i+1} 축">${options([['0','X'],['1','Y'],['2','Z']],String(m.axis))}</select><input type="number" step=".1" min="-100" max="100" data-map="scale" value="${m.scale}" aria-label="${i+1} 배율"><button data-remove="${i}" aria-label="${i+1} 매핑 삭제">${icon('close')}</button></div>`).join('')}</section>`;
  if(kind==='data')form.innerHTML=`<section><div class="form-section-heading"><h3>속성</h3><button data-add>${icon('plus')} 속성 추가</button></div>${d.fields.map((f,i)=>`<div class="data-field-row" data-index="${i}"><input data-value="name" value="${esc(f.name)}" aria-label="${i+1} 속성 이름"><select data-value="type" aria-label="${i+1} 자료형">${options([['string','String'],['float','Float'],['bool','Boolean']],f.type)}</select><input data-value="value" type="${f.type==='bool'?'checkbox':f.type==='float'?'number':'text'}" ${f.type==='bool'?(f.value?'checked':''):`value="${esc(f.value)}"`} aria-label="${i+1} 값"><button data-remove="${i}" aria-label="${i+1} 속성 삭제">${icon('close')}</button></div>`).join('')}</section>`;
  const edit=fn=>{const next=structuredClone(doc.data);fn(next);if(!validAsset(kind,next)){hooks.error('값이나 중복된 이름을 확인하세요.');renderDataEditor(element,doc,files,hooks);return;}hooks.before();doc.data=next;hooks.change();renderDataEditor(element,doc,files,hooks);};
  element.onchange=e=>{const input=e.target,field=input.dataset.field;if(field)edit(d=>d[field]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value);else if(input.dataset.map){const i=Number(input.closest('[data-index]').dataset.index),key=input.dataset.map;edit(d=>d.mappings[i][key]=['axis','scale'].includes(key)?Number(input.value):input.value);}else if(input.dataset.value){const i=Number(input.closest('[data-index]').dataset.index),key=input.dataset.value;edit(d=>{const f=d.fields[i];f[key]=key==='value'?f.type==='bool'?input.checked:f.type==='float'?Number(input.value):input.value:input.value;if(key==='type')f.value={string:'',float:0,bool:false}[input.value];});}};
  element.onclick=e=>{const b=e.target.closest('button');if(!b)return;const key=kind==='inputmapping'?'mappings':'fields';if(b.hasAttribute('data-add'))edit(d=>{if(key==='mappings')d.mappings.push({action:'',key:'E',axis:0,scale:1});else{let index=1;while(d.fields.some(f=>f.name==='Value'+index))index++;d.fields.push({name:'Value'+index,type:'float',value:0});}});else if(b.dataset.remove!==undefined)edit(d=>d[key].splice(Number(b.dataset.remove),1));};
}
export function closeChoice(name){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='close-document-dialog';dialog.innerHTML=`<h2>${esc(name)} 저장</h2><p>저장하지 않은 변경 사항이 있어요.</p><footer><button data-result="cancel">취소</button><button data-result="discard">저장 안 함</button><button data-result="save" class="primary-button">저장</button></footer>`;document.body.append(dialog);let result='cancel';dialog.onclick=e=>{if(e.target.dataset.result){result=e.target.dataset.result;dialog.close();}};dialog.onclose=()=>{dialog.remove();resolve(result);};dialog.showModal();});}
